105	function currentIsoWeek(date = new Date()) {
106	  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
107	  const dayNum = d.getUTCDay() || 7;
108	  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
109	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
110	  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
111	  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
112	}
