4319	// Record a learning event (called after every agent run)
4320	function recordLearning(agentName, taskType, outcome) {
4321	  const db = loadAgentLearning();
4322	
4323	  // Initialize agent profile if missing
4324	  if (!db.agents[agentName]) {
4325	    db.agents[agentName] = {
4326	      totalRuns: 0, successRuns: 0, failedRuns: 0,
4327	      avgDuration: 0, avgTokens: 0, avgCost: 0,
4328	      taskTypes: {}, // per-task-type stats
4329	      streak: 0, bestStreak: 0,
4330	      firstSeen: new Date().toISOString(),
4331	      lastSeen: null,
4332	    };
4333	  }
4334	  const agent = db.agents[agentName];
4335	  agent.totalRuns++;
4336	  agent.lastSeen = new Date().toISOString();
4337	
4338	  if (outcome.success) {
4339	    agent.successRuns++;
4340	    agent.streak = Math.max(0, agent.streak) + 1;
4341	    agent.bestStreak = Math.max(agent.bestStreak, agent.streak);
4342	  } else {
4343	    agent.failedRuns++;
4344	    agent.streak = 0;
4345	  }
4346	
4347	  // Rolling averages (exponential moving average, alpha=0.1)
4348	  const alpha = 0.1;
4349	  agent.avgDuration = agent.avgDuration === 0 ? (outcome.duration || 0) :
4350	    agent.avgDuration * (1 - alpha) + (outcome.duration || 0) * alpha;
4351	  agent.avgTokens = agent.avgTokens === 0 ? (outcome.tokens || 0) :
4352	    agent.avgTokens * (1 - alpha) + (outcome.tokens || 0) * alpha;
4353	  agent.avgCost = agent.avgCost === 0 ? (outcome.cost || 0) :
4354	    agent.avgCost * (1 - alpha) + (outcome.cost || 0) * alpha;
4355	
4356	  // Per task-type stats
4357	  const tt = taskType || 'general';
4358	  if (!agent.taskTypes[tt]) {
4359	    agent.taskTypes[tt] = { runs: 0, successes: 0, avgDuration: 0 };
4360	  }
4361	  const tts = agent.taskTypes[tt];
4362	  tts.runs++;
4363	  if (outcome.success) tts.successes++;
4364	  tts.avgDuration = tts.avgDuration * (1 - alpha) + (outcome.duration || 0) * alpha;
4365	
4366	  // Global task-type stats
4367	  if (!db.taskTypes[tt]) {
4368	    db.taskTypes[tt] = { bestAgent: null, bestRate: 0, agents: {} };
4369	  }
4370	  db.taskTypes[tt].agents[agentName] = {
4371	    successRate: Math.round((tts.successes / tts.runs) * 100),
4372	    avgDuration: Math.round(tts.avgDuration),
4373	    runs: tts.runs,
4374	  };
4375	
4376	  // Update best agent for this task type
4377	  let bestAgent = null, bestRate = 0;
4378	  for (const [name, stats] of Object.entries(db.taskTypes[tt].agents)) {
4379	    if (stats.runs >= 3 && stats.successRate > bestRate) {
4380	      bestRate = stats.successRate;
4381	      bestAgent = name;
4382	    }
4383	  }
4384	  db.taskTypes[tt].bestAgent = bestAgent;
4385	  db.taskTypes[tt].bestRate = bestRate;
4386	
4387	  saveAgentLearning(db);
4388	  return { agent: agentName, taskType: tt, successRate: Math.round((agent.successRuns / agent.totalRuns) * 100) };
4389	}
