---

### 3. JSON Column vs Normalized Decision Matrix

| Data | Decision | Reasoning |
|------|----------|-----------|
| `agent_runs.metadata` | **JSON column** | Small, opaque bag; never filtered on |
| `agents.skills` | **JSON column** | Complex nested map `{react: {score, hits}}`, always read as whole |
| `agents.stats` | **JSON column** | Computed blob, read whole, overwritten whole |
| `agents.breakdown` | **JSON column** | 6 numeric fields, never queried individually |
| `agents.pip` | **JSON column** | Nullable nested object, rare |
| `orchestrations.nodes/edges` | **JSON column** | Complex graph structures with positions, always loaded whole |
| `run_history.nodes/edges/logs/nodeOutputs` | **JSON column** | Large payloads, never queried |
| `reviews.data` | **JSON column** | Entire review snapshot, only queried by week key |
| `chat_sessions.messages` | **NORMALIZED** into `chat_messages` | Enables pagination, counts without loading all messages |
| `project_conversations.messages` | **NORMALIZED** into separate table | Same reason as above |
| `claims.handoffHistory` | **JSON column** | Append-only array, never queried independently |
| `daily_scores.*` | **All scalar** | Every field is filtered/aggregated |
| `witness_log.*` | **Scalar + extra JSON** | Core fields indexed, overflow in `extra` |

---

### 4. The `db.js` Module API Surface

The module exports a function-compatible API so `server.js` swaps `loadX()`/`saveX()` calls with minimal change.

```js
// src/db.js — CommonJS, synchronous, better-sqlite3

const Database = require('better-sqlite3');
const path = require('path');
const fs = require('fs');

const DB_PATH = path.join(__dirname, '..', 'data', 'polyglot.db');

let db;

function getDb() {
  if (db) return db;
  fs.mkdirSync(path.dirname(DB_PATH), { recursive: true });
  db = new Database(DB_PATH);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');
  runMigrations(db);
  return db;
}

module.exports = {
  getDb,
  close: () => { if (db) { db.close(); db = null; } },

  // ── Agent Runs ──────────────────────────────────────────────
  loadAgentRuns,           // () => array (most recent MAX_AGENT_RUNS)
  insertAgentRun,          // (run) => run  (replaces agentRunsQueue + flush)
  queryAgentRuns,          // ({ agent, status, source, from, to, limit, offset }) => { total, runs }
  getAgentRunsSummary,     // () => { [agentName]: { runCount, avgDuration, successRate, ... } }
  getRecentAgentRuns,      // (hours) => array

  // ── Witness Log ─────────────────────────────────────────────
  appendWitnessEvent,      // (entry) => entry
  getWitnessLog,           // ({ agent, days, limit }) => array

  // ── Daily Scores ────────────────────────────────────────────
  appendDailyScore,        // (score) => void
  getDailyScores,          // ({ agent, fromDate, toDate }) => array

  // ── Capability Gaps ─────────────────────────────────────────
  appendCapabilityGap,     // (gap) => void
  getRecentGaps,           // (limit) => array

  // ── Memory Audit Log ────────────────────────────────────────
  loadAuditLog,            // () => array (last 5000)
  appendAuditEntry,        // (entry) => void
  getAuditEntry,           // (id) => entry|null
  getAuditByPath,          // (filePath) => array
  getAuditStats,           // () => { total, byAction, ... }
  clearAuditLog,           // () => void

  // ── Run History (orchestration runs) ────────────────────────
  loadRunHistory,          // () => array (lightweight, no logs)
  getRunHistoryFull,       // (id) => full record with logs
  insertRunHistory,        // (run) => run
  deleteRunHistory,        // (id) => void
  clearRunHistory,         // () => void

  // ── Agents (registry) ──────────────────────────────────────
  loadRegistry,            // () => { version, updatedAt, agents: {} }
  saveRegistry,            // (data) => void
  findAgent,               // (id) => record|null
  upsertAgent,             // (id, patch) => record
  removeAgent,             // (id) => boolean
  listAgentRecords,        // () => array
  findAgentsByDepartment,  // (deptId) => array
  findAgentsByPhase,       // (phaseId) => array
  findDirectReports,       // (managerId) => array

  // ── Departments & Phases ────────────────────────────────────
  loadDepartments,         // () => { departments: {}, phases: {} }
  saveDepartments,         // (data) => void

  // ── Orchestrations ──────────────────────────────────────────
  loadOrchestrations,      // () => array
  saveOrchestration,       // (orc) => void (upsert)
  deleteOrchestration,     // (id) => void

  // ── Schedules ───────────────────────────────────────────────
  loadSchedules,           // () => array
  saveSchedule,            // (schedule) => void (upsert)
  deleteSchedule,          // (id) => void

  // ── Webhooks ────────────────────────────────────────────────
  loadWebhooks,            // () => array
  saveWebhook,             // (webhook) => void (upsert)
  deleteWebhook,           // (id) => void

  // ── Training Corrections ────────────────────────────────────
  loadTraining,            // (agentName) => array
  insertTrainingCorrection, // (agentName, entry) => entry
  updateTrainingCorrection, // (agentName, id, patch) => entry
