  // ── Training Queue (HR) ─────────────────────────────────────
  getTrainingQueue,        // () => { version, updatedAt, items: [] }
  queueTraining,           // (item) => queue
  completeTraining,        // (itemId, outcome) => { ok, item }

  // ── Reviews ─────────────────────────────────────────────────
