#### 6.2 Migration Strategy in Code

```js
// Inside runMigrations(db):

function runMigrations(db) {
  // Create schema_migrations table first
  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (...)`);

  const applied = db.prepare('SELECT version FROM schema_migrations').all().map(r => r.version);

  const migrations = [
    { version: 1, name: 'create_all_tables', fn: createAllTables },
    { version: 2, name: 'import_json_data',  fn: importFromJsonFiles },
  ];

  const runMigration = db.transaction((mig) => {
    mig.fn(db);
    db.prepare('INSERT INTO schema_migrations (version, name) VALUES (?, ?)').run(mig.version, mig.name);
  });

  for (const mig of migrations) {
    if (!applied.includes(mig.version)) {
      console.log(`[db] Running migration ${mig.version}: ${mig.name}`);
      runMigration(mig);
    }
  }
}
```

#### 6.3 JSON Import with Error Handling

```js
function importFromJsonFiles(db) {
  const results = { imported: [], skipped: [], errors: [] };

  // Wrap each file import in its own try/catch so one failure doesn't block others.
  // Use transactions per-file for atomicity.

  const importFile = (label, fn) => {
    try {
      fn();
      results.imported.push(label);
    } catch (err) {
      console.error(`[db:migrate] Failed to import ${label}:`, err.message);
      results.errors.push({ label, error: err.message });
    }
  };

  // Example: agent-runs.json
  importFile('agent-runs.json', () => {
    const filePath = path.join(__dirname, '..', 'agent-runs.json');
    if (!fs.existsSync(filePath)) return;
    const runs = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    if (!Array.isArray(runs) || runs.length === 0) return;

    const stmt = db.prepare(`
      INSERT OR IGNORE INTO agent_runs
        (id, agentName, prompt, source, timestamp, duration, status,
         promptChars, outputChars, estimatedTokens, estimatedCost, error, metadata)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertMany = db.transaction((items) => {
      for (const r of items) {
        stmt.run(r.id, r.agentName, r.prompt, r.source, r.timestamp,
          r.duration, r.status, r.promptChars, r.outputChars,
          r.estimatedTokens, r.estimatedCost, r.error,
          JSON.stringify(r.metadata || {}));
      }
    });
    insertMany(runs);
    fs.renameSync(filePath, filePath + '.migrated');
  });

  // Example: chat-history.json (normalized into two tables)
  importFile('chat-history.json', () => {
    const filePath = path.join(__dirname, '..', 'chat-history.json');
    if (!fs.existsSync(filePath)) return;
    const sessions = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    if (!Array.isArray(sessions) || sessions.length === 0) return;

    const stmtSession = db.prepare(`
      INSERT OR IGNORE INTO chat_sessions (id, title, createdAt, updatedAt)
      VALUES (?, ?, ?, ?)
    `);
    const stmtMessage = db.prepare(`
      INSERT INTO chat_messages (sessionId, role, content, timestamp)
      VALUES (?, ?, ?, ?)
    `);
    const importSessions = db.transaction((items) => {
      for (const s of items) {
        stmtSession.run(s.id, s.title, s.createdAt, s.updatedAt);
        for (const m of (s.messages || [])) {
          stmtMessage.run(s.id, m.role, m.content, m.timestamp || s.updatedAt);
        }
      }
    });
    importSessions(sessions);
    fs.renameSync(filePath, filePath + '.migrated');
  });

  // Example: JSONL file (witness-log.jsonl)
  importFile('witness-log.jsonl', () => {
    const filePath = path.join(HOME, '.claude', 'org', 'witness-log.jsonl');
    if (!fs.existsSync(filePath)) return;
    const lines = fs.readFileSync(filePath, 'utf-8').split('\n').filter(Boolean);

    const stmt = db.prepare(`
      INSERT INTO witness_log (t, agent, runId, class, durationMs, taskType, project, extra)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertMany = db.transaction((entries) => {
      for (const line of entries) {
        try {
          const e = JSON.parse(line);
          const { t, agent, runId, class: cls, durationMs, taskType, project, ...rest } = e;
          stmt.run(t, agent, runId, cls, durationMs, taskType, project, JSON.stringify(rest));
        } catch {}
      }
    });
    insertMany(lines);
    fs.renameSync(filePath, filePath + '.migrated');
  });

  // ... (same pattern for all 26 file sources)
  return results;
}
```

#### 6.4 Rename Strategy

After successful import of each file:
- `agent-runs.json` --> `agent-runs.json.migrated`
- `witness-log.jsonl` --> `witness-log.jsonl.migrated`
- etc.

On next startup, `importFromJsonFiles` checks `fs.existsSync()` first, so `.migrated` files are automatically skipped. This is idempotent and reversible (rename back to restore).

